async handleMessage(@ConnectedSocket() client: Socket, @MessageBody() payload: { chatId: string, content: string, senderId: string }): Promise<void> {
  try {
    const message = await this.chatService.createMessage(payload);
    // Émettre le message à tous les participants du chat
    this.server.to(`chat_${payload.chatId}`).emit('new_message', message);
    // Envoyer une confirmation à l'expéditeur
    client.emit('message_sent', message);
  } catch (error) {
    client.emit('error', { message: error.message });
  }
}
