// dispute.service.ts
@Injectable()
export class DisputeService {
  constructor(@InjectRepository(Dispute) private disputeRepo: Repository<Dispute>) {}

  async createDispute(userId: string, createDisputeDto: CreateDisputeDto): Promise<Dispute> {
    const dispute = this.disputeRepo.create({
      ...createDisputeDto,
      buyerId: userId,
      status: DisputeStatus.OPEN,
    });
    // Logique d'association avec le chat
    return this.disputeRepo.save(dispute);
  }

  async updateStatus(disputeId: string, updateDto: UpdateDisputeStatusDto): Promise<Dispute> {
    const dispute = await this.disputeRepo.findOne({ where: { id: disputeId } });
    if (!dispute) throw new NotFoundException('Litige non trouvé');

    const { status, adminId } = updateDto;
    // Règles de gestion
    if (dispute.status === DisputeStatus.OPEN && status === DisputeStatus.REVIEW) {
      dispute.status = status;
      dispute.adminId = adminId;
    } else if (dispute.status === DisputeStatus.REVIEW && status === DisputeStatus.ESCALATED) {
      dispute.status = status;
      // Logique d'escalade
    } else if (dispute.status === DisputeStatus.REVIEW && status === DisputeStatus.RESOLVED) {
      dispute.status = status;
      // Logique de résolution
    } else {
      throw new BadRequestException('Transition d\'état non autorisée');
    }

    return this.disputeRepo.save(dispute);
  }
}
