// Dans MessageService
async markMessageAsRead(messageId: string, userId: string): Promise<void> {
  const message = await this.messageRepo.findOne({ where: { id: messageId }, relations: ['chat'] });
  if (!message) throw new NotFoundException('Message non trouvé');

  // Vérifier que l'utilisateur fait partie du chat
  const isParticipant = await this.chatService.isUserParticipant(message.chat.id, userId);
  if (!isParticipant) throw new UnauthorizedException();

  message.isRead = true;
  message.readAt = new Date();
  await this.messageRepo.save(message);

  // Émettre l'événement pour mettre à jour l'interface
  this.gateway.server.to(`chat_${message.chat.id}`).emit('message_read', { messageId, userId });
}
