// dispute.service.ts
async resolveDispute(disputeId: string, adminId: string, resolution: string): Promise<Dispute> {
  const dispute = await this.disputeRepo.findOne({
    where: { id: disputeId },
    relations: ['chat', 'buyer', 'seller']
  });
  if (!dispute) throw new NotFoundException('Litige non trouvé');

  if (dispute.status !== DisputeStatus.REVIEW) {
    throw new BadRequestException('Le litige doit être en cours de revue pour être résolu');
  }

  dispute.status = DisputeStatus.RESOLVED;
  dispute.resolution = resolution;
  dispute.resolvedBy = adminId;
  dispute.resolvedAt = new Date();

  const savedDispute = await this.disputeRepo.save(dispute);

  // Déclencher des actions
  this.disputeGateway.notifyDisputeResolved(savedDispute);
  await this.notificationService.notifyDisputeResolution(dispute.buyer, dispute.seller, resolution);
  await this.chatService.closeChat(dispute.chat.id);

  return savedDispute;
}
